import 'package:aes256/aes256.dart';

void main() async {
  final encrypted = await Aes256.encrypt(text: 'Hello world', passphrase: 'my-passphrase');
  final decrypted = await Aes256.decrypt(encrypted: encrypted, passphrase: 'my-passphrase');
  print(decrypted); // Hello world
}
